    "id": "istqb_d_3",
    "exam_id": "istqb_d",
    "exam_title": "ISTQB Sample Exam D (40 câu chuẩn)",
    "group": "ISTQB_EN",
    "q_num": "Question #3",
    "is_bonus": false,
